# ---------------- ch2: the skull ----------------
add(3,"So that is the myth. Is there anything solid underneath it?","white","Cyclops cy_v4 (cutout)","white","hold","existing cy_v4 cutout","Standing cutout on white, ground line",True)
add(3,"In 1914, the palaeontologist Othenio Abel thought there might be.","card","none","flat parchment, cool","hold","CODE:card-abel-book","'Die Tiere der Vorwelt', 1914. Title-page scan if public domain and clean")
add(3,"During the Ice Age, dwarf elephants lived on islands across the Mediterranean:","map","none","flat parchment","hold","CODE:map-dwarf-islands","Dots on Sicily, Malta, Crete, Cyprus, Tilos")
