add(3,"Perhaps the myth came first, and the bones merely seemed to confirm it.","diagram","none","dark ledger","hold","CODE:arrows-which-first (DG-07)","Second state highlights myth > bones")
add(3,"Then there is a problem with the most famous version of this theory.","card","none","flat parchment ledger","hold","CODE:ledger-problem","Stamp: UNVERIFIED",True)
add(3,"Abel claimed that the philosopher Empedocles reported finding such bones on Sicily.","card","none","flat parchment, cool","hold","CODE:card-empedocles","Name and dates; no portrait")
add(3,"Later researchers have found no surviving ancient source that says so.","card","none","flat parchment ledger","hold","CODE:ledger-source-none","Source cell stays blank")
add(3,"The palaeontologist Mark Witton and Richard Hing put it bluntly:","card","none","flat parchment, cool","hold","CODE:card-witton-hing","Names; Interdisciplinary Science Reviews, 2024")
add(3,"without that story, they argue, the idea becomes baseless.","bakedX","none (prop)","firelit edge","push-in","X:NB19 + CODE:overlay-paraphrase","Paraphrase of a line quoted in a secondary source (paper not read; see RESEARCH-V1.md); do not show it as a verbatim quote")
